<?php require __DIR__.'/../config.php';$u=need('teacher');$id=(int)($_GET['id']??0);
// GRADING ONE CODE EXAM: every student of the class with Finished / In progress / Missed, the output check, flags and the grade.
// "Open" shows the student's code and output (or the web page) in the full screen viewer, where you can also go student by student.
$s=$pdo->prepare('SELECT * FROM coding_exams WHERE id=? AND teacher_id=?');$s->execute([$id,$u['id']]);$x=$s->fetch();if(!$x)die('Exam not found');
if($_SERVER['REQUEST_METHOD']==='POST'){check();
if(isset($_POST['end'])){$pdo->prepare('UPDATE coding_exams SET due_at=? WHERE id=?')->execute([date('Y-m-d H:i:s'),$id]);flash('The exam ended now. Students who did not submit are Missed.');}
elseif(isset($_POST['pic_do'])){if($_POST['pic_do']==='remove'){drop_exam_picture($x['attachment']);$pdo->prepare('UPDATE coding_exams SET attachment=NULL,attachment_check=NULL WHERE id=?')->execute([$id]);flash('Picture removed.');}
else{[$nm,$res]=save_exam_picture($_FILES['pic']??null);if($nm){drop_exam_picture($x['attachment']);$pdo->prepare('UPDATE coding_exams SET attachment=?,attachment_check=? WHERE id=?')->execute([$nm,$res,$id]);flash('Picture saved. Students see it beside the problem.');}else flash($res!==''?$res:'Choose a picture first.',true);}}
elseif(isset($_POST['win'])){$err='';[$o,$d]=window_post($err);$cls=teacher_class((int)($_POST['class_id']??0),$u['id']);
if(!$cls)flash('Choose a class.',true);elseif($err)flash($err,true);
else{$pdo->prepare('UPDATE coding_exams SET class_id=?,opens_at=?,due_at=? WHERE id=?')->execute([$cls['id'],$o,$d,$id]);
if((int)$cls['id']!==(int)$x['class_id'])notify_class($cls['id'],'exam','New code exam in '.class_name($cls).': '.$x['title'].' (due '.when($d).')','Exam/exams.php');
elseif($d!==$x['due_at'])notify_class($cls['id'],'exam','Deadline changed: '.$x['title'].' is now due '.when($d),'Exam/exams.php');
flash('Saved. '.class_name($cls).', opens '.when($o).', deadline '.when($d).'.');}}
elseif(exam_grade($x,$_POST['aid']??0,$_POST['score']??0,$_POST['feedback']??''))flash('Grade saved. The student was notified.');
header('Location: '.BASE.'Exam/exam_results.php?id='.$id);exit;}
head('Grading: '.$x['title']);flash();$T='<input type="hidden" name="t" value="'.csrf().'">';
echo '<div class="card" style="max-width:none"><div class="chead"><div>'.teacher_state($x).' <small>&middot; '.e(lname($x['language'])).', '.(int)$x['minutes'].' min, '.(int)$x['max_points'].' points</small></div><form method="post" class="inl" style="margin:0" onsubmit="return confirm(\'End this exam now? Students who did not submit become Missed.\')">'.$T.'<input type="hidden" name="end" value="1"><button class="alt">End now</button></form></div>
<details'.($x['class_id']?'':' open').'><summary>Change the class, start time or deadline</summary><form method="post">'.$T.'<input type="hidden" name="win" value="1">'.class_select($u,$x['class_id']).window_fields($x['opens_at'],$x['due_at']).'<button class="alt">Save</button> <small>A new class is notified. A new deadline is told to the class.</small></form></details>
<details'.($x['attachment']?' open':'').'><summary>Picture of the expected output'.($x['attachment']?' (1)':'').'</summary>'.picture_html($x).'<form method="post" enctype="multipart/form-data" class="inl" style="flex-wrap:wrap">'.$T.'<input type="hidden" name="pic_do" value="save"><input type="file" name="pic" accept="image/png,image/jpeg,image/gif,image/webp" required style="max-width:22rem"><button class="alt">'.($x['attachment']?'Replace picture':'Upload picture').'</button></form>'.($x['attachment']?'<form method="post" class="inl">'.$T.'<input type="hidden" name="pic_do" value="remove"><button class="alt">Remove picture</button></form>':'').'<small>Pictures only (PNG, JPG, GIF, WEBP, up to 5 MB). Pictures not appropriate for school are blocked.</small></details></div>';
$q="SELECT u.id uid,u.full_name,u.student_id sid,a.id aid,a.submitted_at,a.passed,a.score,a.feedback,(SELECT COUNT(*) FROM exam_events c WHERE c.attempt_id=a.id AND c.event_type IN ".FLAG_SQL.") fl,(SELECT GROUP_CONCAT(DISTINCT c.event_type) FROM exam_events c WHERE c.attempt_id=a.id AND c.event_type IN ".FLAG_SQL.") ty FROM users u ";
$s=$pdo->prepare($q."JOIN class_members m ON m.student_id=u.id AND m.class_id=? LEFT JOIN exam_attempts a ON a.exam_id=? AND a.student_id=u.id ORDER BY u.full_name");$s->execute([(int)$x['class_id'],$id]);$rows=$s->fetchAll();
$s=$pdo->prepare($q."JOIN exam_attempts a ON a.student_id=u.id AND a.exam_id=? WHERE u.id NOT IN (SELECT student_id FROM class_members WHERE class_id=?) ORDER BY u.full_name");$s->execute([$id,(int)$x['class_id']]);$rows=array_merge($rows,$s->fetchAll()); // started it, then left the class
$done=count(array_filter($rows,fn($r)=>$r['submitted_at']));$miss=count(array_filter($rows,fn($r)=>work_state($x+['aid'=>$r['aid'],'submitted_at'=>$r['submitted_at']])[0]==='missed'));
echo '<div class="stats"><div class="card"><h3>Finished</h3><div class="big" style="color:var(--ok)">'.$done.'</div><small>of '.count($rows).' students</small></div><div class="card"><h3>Missed</h3><div class="big" style="color:var(--bad)">'.$miss.'</div></div><div class="card"><h3>To grade</h3><div class="big">'.count(array_filter($rows,fn($r)=>$r['submitted_at']&&$r['score']===null)).'</div></div></div>';
$first=array_values(array_filter($rows,fn($r)=>$r['submitted_at']));
if($first)echo '<p><a class="btn" href="Exam/view.php?aid='.(int)$first[0]['aid'].'">'.ico('full').' Open the submissions in full screen</a> <small>Code and output of each student, one after the other, with the grade box.</small></p>';
table(['Student','Status','Output matched','Left the page','Grade',''],array_map(function($r)use($T,$x){$a=(int)$r['aid'];$d=$a&&$r['submitted_at'];[$k,$t]=work_state($x+['aid'=>$r['aid'],'submitted_at'=>$r['submitted_at']]);
return [e($r['full_name']).'<br><small>'.e($r['sid']).'</small>','<span class="st st-'.$k.'">'.($k==='open'?'Not started':$t).'</span>'.($d?'<br><small>'.e(when($r['submitted_at'])).'</small>':''),$d?(in_array($x['language'],['html','web'],true)?'Look at the page':($r['passed']?'<span class="ok">Yes</span>':'No')):'-',$a?$r['fl'].'<br><small>'.e(flag_words($r['ty'])).'</small>':'-',
$d?'<form method="post" class="inl">'.$T.'<input type="hidden" name="aid" value="'.$a.'"><input type="number" name="score" min="0" max="'.(int)$x['max_points'].'" value="'.($r['score']===null?'':(int)$r['score']).'" style="width:5rem" required><input name="feedback" placeholder="Feedback" value="'.e($r['feedback']).'" maxlength="500"><button class="alt">Save</button></form>':'-',
$d?'<a class="btn alt" href="Exam/view.php?aid='.$a.'">Open</a>':''];},$rows));
foot();
